def transform(grid):
    h, w = len(grid), len(grid[0])
    gray = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    rows = [r for r, c in gray]
    cols = [c for r, c in gray]
    r0, r1, c0, c1 = min(rows), max(rows), min(cols), max(cols)
    zero_rows = [r for r in range(h) if grid[r].count(0) >= w // 2]
    zero_cols = [c for c in range(w) if sum(grid[r][c] == 0 for r in range(h)) >= h // 2]
    out = [[7] * w for _ in range(h)]
    if any(r0 <= r <= r1 for r in zero_rows):
        for r in zero_rows:
            out[r] = [0] * w
        mid = (c0 + c1) // 2
        for r in range(h):
            for c in (mid - 1, mid, mid + 1):
                if 0 <= c < w:
                    out[r][c] = 0
            start = (h - len(gray)) // 2
            out[r][mid] = 5 if start <= r < start + len(gray) else 7
    else:
        for c in zero_cols:
            for r in range(h):
                out[r][c] = 0
        mid = (r0 + r1) // 2
        for r in (mid - 1, mid + 1):
            if 0 <= r < h:
                out[r] = [0] * w
        for c in zero_cols:
            for r in (mid - 1, mid + 1):
                if 0 <= r < h:
                    out[r][c] = 0
        start = (w - len(gray)) // 2
        for c in range(start, start + len(gray)):
            out[mid][c] = 5
    return out

